<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserApproveOptions;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserApproveAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserApproveAccessor trait.
 *
 * Covers null default, string/VO assignment via withApprove,
 * getApprove/approve accessors, and isApproveChanged with/without original.
 */
class UserApproveAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withApprove creates a new instance with the Approve set
     * from a string value, and getApprove returns the primitive string.
     */
    public function testWithApproveFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserApproveAccessorUnitTest();

        // Act
        $result = $holder->withApprove(UserApproveOptions::UNVERIFIED);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(UserApproveOptions::UNVERIFIED, $result->getApprove());
    }
    /**
     * Asserts that withapprove has access to the value object
     * from a string value, and getApprove returns the primitive string.
     */
    public function testWithApproveFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserApproveAccessorUnitTest();

        // Act
        $result = $holder->withApprove(UserApproveOptions::UNVERIFIED);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(UserApproveOptions::UNVERIFIED, $result->approve()->value());
    }
    public function testChangedApprove(): void
    {
        // Arrange
        $holder = new ImplWithUserApproveAccessorUnitTest();
        $original = $holder->withApprove(UserApproveOptions::UNVERIFIED);
        $same = $holder->withApprove(UserApproveOptions::UNVERIFIED);
        $modified = $holder->withApprove(UserApproveOptions::PENDING);

        // Act
        $unchanged = $holder->isApproveChanged();
        $withSame = $original->isApproveChanged($same);
        $withDiferent = $original->isApproveChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserApproveAccessorUnitTest
{
    use UserApproveAccessor;
}
